const WEB_DID_RE = /^did:web:([a-zA-Z0-9%-]+(?:(?:\.[a-zA-Z0-9%-]+)*(?:\.[a-zA-Z]{2,}))?)?((?::[a-zA-Z0-9\-%.]+)+)?$/;
const ATPROTO_WEB_DID_RE = /^did:web:([a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)*(?:\.[a-zA-Z]{2,})|localhost(?:%3[aA]\d+)?)$/;
/**
 * checks if input is a did:web identifier, note that you should probably use `isAtprotoWebDid` for
 * atproto-related cases as atproto only supports a subset of the did:web specification (namely, no custom
 * paths)
 */
export const isWebDid = (input) => {
    return typeof input === 'string' && input.length >= 9 && WEB_DID_RE.test(input);
};
/** checks if input is a did:web identifier that is supported by atproto */
export const isAtprotoWebDid = (input) => {
    return typeof input === 'string' && input.length >= 12 && ATPROTO_WEB_DID_RE.test(input);
};
/** normalize a did:web identifier */
export const normalizeWebDid = (did) => {
    // keep path segments verbatim; decoding them would split a percent-encoded colon into two segments
    const [host, ...paths] = did.slice(8).split(':');
    let normalized = `did:web:${encodeURIComponent(decodeURIComponent(host).toLowerCase())}`;
    if (paths.length > 0) {
        normalized += `:${paths.join(':')}`;
    }
    return normalized;
};
/** converts did:web identifier into the DID document's URL */
export const webDidToDocumentUrl = (did) => {
    const [host, ...paths] = did.slice(8).split(':').map(decodeURIComponent);
    let pathname = '/' + paths.join('/');
    if (pathname === '/') {
        pathname = `/.well-known/did.json`;
    }
    else {
        pathname += `/did.json`;
    }
    const url = new URL(`https://${host}${pathname}`);
    if (url.hostname === 'localhost') {
        url.protocol = 'http:';
    }
    return url;
};
