import {
  Color,
  PerspectiveCamera,
  Scene,
  WebGLRenderer,
} from "@random-mesh/rmsl/scene";
import { AdaptiveResolution } from "./adaptive";
import { createGpuTimer, type GpuTimerApi } from "./perf";
import { Field, Phase, probe } from "./perf-probe";

/** How many frames between each debug-perf GPU readback, which stalls the pipeline. */
const SAMPLE_EVERY = 24;

/** How long the resolution is left alone after the page becomes visible again, in frames. */
const RETURN_HOLD_FRAMES = 60;

export interface RenderLoopConfig {
  canvas: HTMLCanvasElement;
  scene: Scene;
  /**
   * What the frame is drawn from. A getter lets one loop follow whichever
   * camera is active — the player's, or the level editor's orbit camera —
   * without being torn down and remounted.
   */
  camera: PerspectiveCamera | (() => PerspectiveCamera);
  /** The colour to clear to, read once per frame after `onFrame` has run. */
  clearColor: () => Color;
  /**
   * Whether to time the frame on the GPU and assemble the statistics line.
   * Read once a frame, so it can be turned on and off while the loop runs.
   */
  debugPerf: () => boolean;
  /**
   * The scaler deciding this canvas's render resolution, shared with whatever
   * else reads or sets it and outliving any one mounted canvas. A loop given
   * none keeps a scaler of its own for as long as it runs.
   */
  resolution?: AdaptiveResolution;
  /** Advances the world by `dt` seconds. Called once per frame, before drawing. */
  onFrame: (dt: number) => void;
  /**
   * Runs once per frame, just before the scene is drawn, with the renderer
   * and camera — the slot for a pass the visible draw must not capture (an
   * occlusion readback) to run first on the same context and the same camera
   * view.
   */
  beforeRender?: (renderer: WebGLRenderer, camera: PerspectiveCamera) => void;
  /**
   * Called with the canvas straight after the frame is drawn and before
   * anything can clear it. A WebGL drawing buffer is not readable at any other
   * moment unless the context is asked to preserve it, which costs every frame
   * to serve the rare one somebody wants a picture of.
   */
  afterRender?: (canvas: HTMLCanvasElement) => void;
  /**
   * Renderer statistics to append to the debug line. `sample` is true only on
   * the frames where a GPU readback is affordable.
   */
  describeStats?: (
    gl: WebGL2RenderingContext,
    width: number,
    height: number,
    sample: boolean,
  ) => string;
  /** Receives the assembled debug line once per frame while `debugPerf` is on. */
  onDebugStats?: (line: string) => void;
  /**
   * Whether the canvas is drawn multisampled, smoothing the edges where one
   * surface ends and the next begins. Defaults to on, as WebGL itself does.
   *
   * It is a context attribute, decided when the context is made and fixed for
   * its life, and what it costs is memory rather than time: a multisampled
   * canvas holds several samples of every pixel, which on a phone's screen is
   * the largest thing the page keeps on the graphics card.
   */
  antialias?: boolean;
}

export interface RenderLoop {
  /** Stops the loop, stops watching the canvas, and releases the renderer's GPU resources. */
  dispose(): void;
}

/**
 * Drives one canvas: a renderer, the frame loop, and the resolution scaler it
 * feeds each frame's gap to. Knows nothing about what it draws beyond the
 * scene and camera handed to it.
 */
export const createRenderLoop = ({
  canvas,
  scene,
  camera,
  debugPerf,
  resolution,
  onFrame,
  beforeRender,
  afterRender,
  clearColor,
  describeStats,
  onDebugStats,
  antialias,
}: RenderLoopConfig): RenderLoop => {
  const renderer = new WebGLRenderer(canvas, { antialias });
  renderer.setClearColor(clearColor(), 1);
  /** The camera this frame draws from, resolving the config's getter if given. */
  const viewCamera = (): PerspectiveCamera =>
    typeof camera === "function" ? camera() : camera;
  /** Built the first frame the statistics are asked for, and kept from then on. */
  let timer: GpuTimerApi | undefined;
  /**
   * Times the occlusion pass on the graphics card separately from the draw.
   * The pass exists to save the card work, so what it costs the card is the
   * other half of whether it is worth running.
   */
  let occlusionTimer: GpuTimerApi | undefined;

  const adaptive = resolution ?? new AdaptiveResolution();
  /** The canvas's layout size in device pixels; the scale is applied on top of it. */
  let baseWidth = 0;
  let baseHeight = 0;
  let lastAdaptTime = 0;
  let lastFrameTime = 0;
  let frameCounter = 0;

  /**
   * Draws one frame.
   *
   * @returns Whether this frame took a GPU readback for the statistics line.
   * Those frames stall the pipeline, so their timing can't be used to decide
   * the resolution.
   */
  const render = (): boolean => {
    const showStats = debugPerf();
    const view = viewCamera();
    if (!showStats && !probe.armed) {
      beforeRender?.(renderer, view);
      renderer.render(scene, view);
      // Handed over on this path as well as the timed one: whether a frame is
      // being measured has nothing to do with whether somebody wants a picture
      // of it, and a world nobody is measuring is the ordinary case.
      afterRender?.(canvas);
      return false;
    }
    timer ??= createGpuTimer(renderer.gl);
    occlusionTimer ??= createGpuTimer(renderer.gl);
    occlusionTimer.begin();
    probe.begin(Phase.occlusion);
    beforeRender?.(renderer, view);
    probe.end(Phase.occlusion);
    occlusionTimer.end();
    occlusionTimer.poll();
    timer.begin();
    probe.begin(Phase.draw);
    renderer.render(scene, view);
    probe.end(Phase.draw);
    afterRender?.(canvas);
    timer.end();
    timer.poll();
    frameCounter++;
    const sample = frameCounter % SAMPLE_EVERY === 0;
    if (!showStats) {
      return sample;
    }
    const stats = describeStats?.(
      renderer.gl,
      renderer.canvas.width,
      renderer.canvas.height,
      sample,
    );
    onDebugStats?.(
      `frame: ${timer.ms.toFixed(2)} ms | resolution: ${adaptive.scale.toFixed(3)}x | ${stats ?? ""}`,
    );
    return sample;
  };

  const applyResolution = (scale: number): void => {
    if (baseWidth <= 0 || baseHeight <= 0) {
      return;
    }
    const width = Math.max(1, Math.round(baseWidth * scale));
    const height = Math.max(1, Math.round(baseHeight * scale));
    if (width !== canvas.width || height !== canvas.height) {
      canvas.width = width;
      canvas.height = height;
      // A buffer smaller than the box it fills is stretched by the browser,
      // and smoothing that stretch spreads each surface over the dark seam
      // beside it — the world reads as lit flatter and brighter the further
      // the scale drops. Enlarging the pixels instead keeps every edge where
      // the frame put it. Only while it is being stretched: a display with
      // more device pixels than layout pixels leaves the buffer larger than
      // the box at full scale, and there the smoothing is what turns those
      // extra pixels into a finer image rather than a sparser sample of one.
      canvas.style.imageRendering =
        width < baseWidth / window.devicePixelRatio ? "pixelated" : "";
      // Resizing the canvas clears its drawing buffer to transparent, which
      // would flash the page background until the next RAF frame. Draw the new
      // resolution immediately so the compositor never shows the cleared buffer.
      render();
    }
  };

  const animate = (time: number): void => {
    const gapMs = lastFrameTime > 0 ? time - lastFrameTime : 0;
    const dt =
      lastFrameTime > 0
        ? Math.min(0.05, (time - lastFrameTime) / 1000)
        : 1 / 60;
    lastFrameTime = time;
    probe.begin(Phase.advance);
    onFrame(dt);
    probe.end(Phase.advance);
    renderer.setClearColor(clearColor(), 1);
    const sampled = render();
    if (occlusionTimer !== undefined && occlusionTimer.answered) {
      probe.gauge(Field.gpuOcclusionMs, occlusionTimer.ms);
    }
    probe.frame(
      gapMs,
      timer !== undefined && timer.answered ? timer.ms : -1,
      adaptive.scale,
    );
    // A hidden page still gets frames, roughly one a second rather than sixty,
    // and every one of them misses its deadline by any measure taken here. The
    // resolution would walk itself down for as long as the player was in
    // another tab, so nothing is measured while they are.
    if (lastAdaptTime > 0 && !document.hidden) {
      const frameMs = time - lastAdaptTime;
      applyResolution(
        sampled ? adaptive.frame(frameMs) : adaptive.update(frameMs),
      );
    }
    lastAdaptTime = time;
  };

  /**
   * Discards the timing carried over from before the page was hidden. The
   * first frame back would otherwise report the whole time away as one
   * frame's gap, and the frames after it pay for textures and programs the
   * browser reclaimed in the background, so neither is measured.
   */
  const onVisibilityChange = (): void => {
    if (document.visibilityState !== "visible") {
      return;
    }
    lastAdaptTime = 0;
    lastFrameTime = 0;
    adaptive.hold(RETURN_HOLD_FRAMES);
  };
  document.addEventListener("visibilitychange", onVisibilityChange);

  const resizeObserver = new ResizeObserver(() => {
    const rect = canvas.getBoundingClientRect();
    const aspect = rect.width / rect.height;
    if (!Number.isFinite(aspect) || aspect <= 0) {
      return;
    }
    baseWidth = rect.width * window.devicePixelRatio;
    baseHeight = rect.height * window.devicePixelRatio;
    const view = viewCamera();
    view.aspect = aspect;
    view.updateProjectionMatrix();
    // a layout change changes the render cost, so hold adaptation while
    // the new base resolution settles
    adaptive.hold();
    applyResolution(adaptive.scale);
  });
  resizeObserver.observe(canvas);
  renderer.setAnimationLoop(animate);

  return {
    dispose() {
      document.removeEventListener("visibilitychange", onVisibilityChange);
      resizeObserver.disconnect();
      renderer.setAnimationLoop(null);
      // release the renderer's GPU programs, buffers and textures
      renderer.dispose();
    },
  };
};
